import React, { useState, useEffect } from 'react';
import {
  Container,
  Box,
  Typography,
  Paper,
  CircularProgress,
  Alert,
} from '@mui/material';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import remarkMath from 'remark-math';
import rehypeKatex from 'rehype-katex';
import { Prism as SyntaxHighlighter } from 'react-syntax-highlighter';
import { vscDarkPlus } from 'react-syntax-highlighter/dist/esm/styles/prism';
import 'katex/dist/katex.min.css';
import './NotebookViewer.css';

// Try to import the notebooks manifest (generated by script)
let notebooksManifest = null;
try {
  // eslint-disable-next-line import/no-unresolved
  notebooksManifest = require('./notebooks-manifest.json');
} catch (error) {
  console.warn('Notebooks manifest not found. Run "npm run generate-notebooks-manifest" to generate it.');
}

const NotebookViewer = ({ notebookPath }) => {
  const [notebook, setNotebook] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const loadNotebook = async () => {
      try {
        setLoading(true);
        setError(null);
        
        // Fetch the notebook file
        const response = await fetch(notebookPath);
        if (!response.ok) {
          throw new Error(`Failed to load notebook: ${response.statusText}`);
        }
        
        const data = await response.json();
        
        // Validate it's a Jupyter notebook
        if (!data.cells || !Array.isArray(data.cells)) {
          throw new Error('Invalid notebook format: missing cells array');
        }
        
        setNotebook(data);
      } catch (err) {
        setError(err.message);
        console.error('Error loading notebook:', err);
      } finally {
        setLoading(false);
      }
    };

    if (notebookPath) {
      loadNotebook();
    }
  }, [notebookPath]);

  const renderOutput = (output) => {
    if (!output) return null;

    const outputType = output.output_type;
    const data = output.data || {};

    // Handle different output types
    if (outputType === 'stream') {
      const text = output.text || '';
      return (
        <Box
          sx={{
            marginTop: 1,
            maxHeight: '400px',
            overflowY: 'auto',
            overflowX: 'auto',
            borderRadius: 1,
          }}
        >
          <Box
            component="pre"
            sx={{
              fontFamily: 'monospace',
              fontSize: '0.9rem',
              lineHeight: 1.6,
              margin: 0,
              padding: 2,
              backgroundColor: '#f5f5f5',
              borderRadius: 1,
              whiteSpace: 'pre',
              minWidth: 'fit-content',
            }}
          >
            {Array.isArray(text) ? text.join('') : text}
          </Box>
        </Box>
      );
    }

    if (outputType === 'error') {
      const traceback = output.traceback || [];
      const errorName = output.ename || 'Error';
      const errorValue = output.evalue || '';
      
      return (
        <Box
          sx={{
            backgroundColor: '#fee',
            borderLeft: '4px solid #f44336',
            padding: 2,
            borderRadius: 1,
            marginTop: 1,
            maxHeight: '400px',
            overflowY: 'auto',
            overflowX: 'auto',
          }}
        >
          <Typography variant="subtitle2" sx={{ color: '#c62828', fontWeight: 600, mb: 1, fontFamily: "'Source Serif 4', serif" }}>
            {errorName}: {errorValue}
          </Typography>
          {traceback.length > 0 && (
            <Box
              component="pre"
              sx={{
                fontFamily: 'monospace',
                fontSize: '0.85rem',
                margin: 0,
                whiteSpace: 'pre',
                color: '#c62828',
                minWidth: 'fit-content',
              }}
            >
              {traceback.join('\n')}
            </Box>
          )}
        </Box>
      );
    }

    if (outputType === 'execute_result' || outputType === 'display_data') {
      // Handle images FIRST (prioritize over text/plain for matplotlib outputs)
      if (data['image/png']) {
        const imageData = data['image/png'];
        return (
          <Box 
            sx={{ 
              marginTop: 1, 
              textAlign: 'left',
              maxHeight: '600px',
              overflowY: 'auto',
              overflowX: 'auto',
              borderRadius: 1,
            }}
          >
            <img
              src={`data:image/png;base64,${imageData}`}
              alt="Notebook output"
              style={{
                maxWidth: 'none',
                width: 'auto',
                height: 'auto',
                borderRadius: 8,
                boxShadow: '0 2px 8px rgba(0,0,0,0.1)',
                display: 'block',
              }}
            />
          </Box>
        );
      }

      if (data['image/jpeg'] || data['image/jpg']) {
        const imageData = data['image/jpeg'] || data['image/jpg'];
        return (
          <Box 
            sx={{ 
              marginTop: 1, 
              textAlign: 'left',
              maxHeight: '600px',
              overflowY: 'auto',
              overflowX: 'auto',
              borderRadius: 1,
            }}
          >
            <img
              src={`data:image/jpeg;base64,${imageData}`}
              alt="Notebook output"
              style={{
                maxWidth: 'none',
                width: 'auto',
                height: 'auto',
                borderRadius: 8,
                boxShadow: '0 2px 8px rgba(0,0,0,0.1)',
                display: 'block',
              }}
            />
          </Box>
        );
      }

      // Handle HTML
      if (data['text/html']) {
        const html = Array.isArray(data['text/html']) 
          ? data['text/html'].join('') 
          : data['text/html'];
        return (
          <Box
            sx={{
              marginTop: 1,
              maxHeight: '600px',
              overflowY: 'auto',
              overflowX: 'auto',
              borderRadius: 1,
              '& img': {
                maxWidth: 'none',
                width: 'auto',
                height: 'auto',
                borderRadius: 1,
              },
            }}
            dangerouslySetInnerHTML={{ __html: html }}
          />
        );
      }

      // Handle text/plain (but skip matplotlib figure descriptions)
      if (data['text/plain']) {
        const text = Array.isArray(data['text/plain']) 
          ? data['text/plain'].join('') 
          : data['text/plain'];
        
        // Skip matplotlib figure descriptions like "<Figure size 640x480 with 1 Axes>"
        if (typeof text === 'string' && text.trim().match(/^<Figure size \d+x\d+ with \d+ Axes>$/)) {
          return null; // Don't display matplotlib figure text when image is available
        }
        
        return (
          <Box
            sx={{
              marginTop: 1,
              maxHeight: '400px',
              overflowY: 'auto',
              overflowX: 'auto',
              borderRadius: 1,
            }}
          >
            <Box
              component="pre"
              sx={{
                fontFamily: 'monospace',
                fontSize: '0.9rem',
                lineHeight: 1.6,
                margin: 0,
                padding: 2,
                backgroundColor: '#f5f5f5',
                borderRadius: 1,
                whiteSpace: 'pre',
                minWidth: 'fit-content',
              }}
            >
              {text}
            </Box>
          </Box>
        );
      }

      // Handle LaTeX/Math
      if (data['text/latex']) {
        const latex = Array.isArray(data['text/latex']) 
          ? data['text/latex'].join('') 
          : data['text/latex'];
        return (
          <Box 
            sx={{ 
              marginTop: 1, 
              padding: 2, 
              backgroundColor: '#f5f5f5', 
              borderRadius: 1,
              maxHeight: '400px',
              overflowY: 'auto',
              overflowX: 'auto',
            }}
          >
            <ReactMarkdown 
              remarkPlugins={[remarkMath]}
              rehypePlugins={[rehypeKatex]}
            >
              {`$$${latex}$$`}
            </ReactMarkdown>
          </Box>
        );
      }
    }

    return null;
  };

  const renderCell = (cell, index) => {
    const cellType = cell.cell_type;
    const source = cell.source || '';

    // Join source array if it's an array
    const sourceText = Array.isArray(source) ? source.join('') : source;

    if (cellType === 'markdown') {
      return (
        <Box
          key={index}
          className="notebook-cell notebook-markdown"
          sx={{
            marginBottom: 4,
            textAlign: 'left',
            '& p': {
              marginBottom: '1.5rem',
              lineHeight: 1.8,
              fontSize: '1.1rem',
              color: '#333',
              textAlign: 'left',
            },
            '& h1': {
              marginTop: '2rem',
              marginBottom: '1rem',
              fontSize: '2.5rem',
              fontWeight: 700,
              lineHeight: 1.2,
              textAlign: 'left',
            },
            '& h2': {
              marginTop: '2rem',
              marginBottom: '1rem',
              fontSize: '2rem',
              fontWeight: 600,
              lineHeight: 1.3,
              textAlign: 'left',
            },
            '& h3': {
              marginTop: '1.5rem',
              marginBottom: '0.75rem',
              fontSize: '1.5rem',
              fontWeight: 600,
              lineHeight: 1.4,
              textAlign: 'left',
            },
            '& ul, & ol': {
              marginBottom: '1.5rem',
              paddingLeft: '2rem',
            },
            '& li': {
              marginBottom: '0.5rem',
              lineHeight: 1.8,
            },
            '& blockquote': {
              borderLeft: '4px solid #1e40af',
              paddingLeft: '1.5rem',
              marginLeft: 0,
              marginBottom: '1.5rem',
              fontStyle: 'italic',
              color: '#666',
            },
            '& code': {
              backgroundColor: '#f5f5f5',
              padding: '0.2em 0.4em',
              borderRadius: '3px',
              fontSize: '0.9em',
              fontFamily: 'monospace',
            },
            '& pre': {
              backgroundColor: '#f5f5f5',
              padding: '1rem',
              borderRadius: '8px',
              overflowX: 'auto',
              marginBottom: '1.5rem',
            },
            '& pre code': {
              backgroundColor: 'transparent',
              padding: 0,
            },
            '& table': {
              width: '100%',
              borderCollapse: 'collapse',
              marginBottom: '1.5rem',
            },
            '& th, & td': {
              border: '1px solid #ddd',
              padding: '0.75rem',
              textAlign: 'left',
            },
            '& th': {
              backgroundColor: '#f5f5f5',
              fontWeight: 600,
            },
            '& img': {
              maxWidth: '100%',
              height: 'auto',
              borderRadius: '8px',
              marginTop: '1rem',
              marginBottom: '1rem',
            },
            '& a': {
              color: '#1e40af',
              textDecoration: 'none',
              '&:hover': {
                textDecoration: 'underline',
              },
            },
          }}
        >
          <ReactMarkdown 
            remarkPlugins={[remarkGfm, remarkMath]}
            rehypePlugins={[rehypeKatex]}
          >
            {sourceText}
          </ReactMarkdown>
        </Box>
      );
    }

    if (cellType === 'code') {
      const outputs = cell.outputs || [];
      const language = cell.metadata?.language || 'python';

      return (
        <Box key={index} className="notebook-cell notebook-code" sx={{ marginBottom: 4 }}>
          <Paper
            elevation={0}
            sx={{
              backgroundColor: '#1e1e1e',
              borderRadius: 2,
              overflow: 'hidden',
              border: '1px solid #333',
            }}
          >
            <Box
              sx={{
                backgroundColor: '#252526',
                padding: '0.5rem 1rem',
                borderBottom: '1px solid #333',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'space-between',
              }}
            >
              <Typography
                variant="caption"
                sx={{
                  color: '#858585',
                  fontSize: '0.75rem',
                  textTransform: 'uppercase',
                  letterSpacing: '0.5px',
                }}
              >
                {language}
              </Typography>
            </Box>
            <SyntaxHighlighter
              language={language}
              style={vscDarkPlus}
              customStyle={{
                margin: 0,
                padding: '1rem',
                fontSize: '0.9rem',
                lineHeight: 1.6,
                backgroundColor: '#1e1e1e',
              }}
              showLineNumbers={false}
            >
              {sourceText}
            </SyntaxHighlighter>
          </Paper>

          {/* Render outputs */}
          {outputs.length > 0 && (
            <Box sx={{ marginTop: 2 }}>
              {outputs.map((output, outputIndex) => (
                <Box key={outputIndex}>
                  {renderOutput(output)}
                </Box>
              ))}
            </Box>
          )}
        </Box>
      );
    }

    if (cellType === 'raw') {
      return (
        <Box
          key={index}
          className="notebook-cell notebook-raw"
          sx={{
            marginBottom: 4,
            padding: 2,
            backgroundColor: '#f9f9f9',
            borderRadius: 1,
            border: '1px solid #e0e0e0',
          }}
        >
          <Typography
            variant="caption"
            sx={{
              display: 'block',
              marginBottom: 1,
              color: '#666',
              fontWeight: 600,
              fontFamily: "'Source Serif 4', serif",
            }}
          >
            Raw Cell
          </Typography>
          <Box
            component="pre"
            sx={{
              fontFamily: 'monospace',
              fontSize: '0.9rem',
              margin: 0,
              whiteSpace: 'pre-wrap',
              wordBreak: 'break-word',
            }}
          >
            {sourceText}
          </Box>
        </Box>
      );
    }

    return null;
  };

  if (loading) {
    return (
      <Container maxWidth="md" sx={{ py: 8, textAlign: 'left' }}>
        <CircularProgress />
        <Typography variant="body1" sx={{ mt: 2, color: 'text.secondary', fontFamily: "'Source Serif 4', serif" }}>
          Loading notebook...
        </Typography>
      </Container>
    );
  }

  if (error) {
    return (
      <Container maxWidth="md" sx={{ py: 8 }}>
        <Alert severity="error">
          <Typography variant="h6" gutterBottom sx={{ fontFamily: "'Source Serif 4', serif" }}>
            Error loading notebook
          </Typography>
          <Typography variant="body2" sx={{ fontFamily: "'Source Serif 4', serif" }}>{error}</Typography>
        </Alert>
      </Container>
    );
  }

  if (!notebook) {
    return (
      <Container maxWidth="md" sx={{ py: 8 }}>
        <Alert severity="info">
          <Typography sx={{ fontFamily: "'Source Serif 4', serif" }}>
            No notebook path provided. Please specify a notebook file to display.
          </Typography>
        </Alert>
      </Container>
    );
  }

  // Extract filename from notebookPath to look up override title
  const filename = notebookPath ? notebookPath.split('/').pop() : null;
  const notebookFromManifest = filename && notebooksManifest?.notebooks?.find(nb => nb.filename === filename);
  
  const metadata = notebook.metadata || {};
  // Use override title from manifest if available, otherwise fall back to notebook metadata
  const title = notebookFromManifest?.title || metadata.title || 'Notebook';

  return (
    <Container maxWidth="md" className="notebook-viewer" sx={{ py: { xs: 4, md: 6 }, textAlign: 'left' }}>
      <Box sx={{ mb: 6, textAlign: 'left' }}>
        <Typography
          variant="h3"
          component="h1"
          sx={{
            fontWeight: 700,
            marginBottom: 2,
            color: '#1e40af',
            lineHeight: 1.2,
            textAlign: 'left',
            fontFamily: "'Source Serif 4', serif",
          }}
        >
          {title}
        </Typography>
        {metadata.authors && (
          <Typography variant="body1" color="text.secondary" sx={{ mb: 1, textAlign: 'left', fontFamily: "'Source Serif 4', serif" }}>
            {Array.isArray(metadata.authors) 
              ? metadata.authors.join(', ') 
              : metadata.authors}
          </Typography>
        )}
        {metadata.date && (
          <Typography variant="body2" color="text.secondary" sx={{ textAlign: 'left', fontFamily: "'Source Serif 4', serif" }}>
            {new Date(metadata.date).toLocaleDateString('en-US', {
              year: 'numeric',
              month: 'long',
              day: 'numeric',
            })}
          </Typography>
        )}
      </Box>

      <Box className="notebook-content" sx={{ textAlign: 'left' }}>
        {notebook.cells.map((cell, index) => renderCell(cell, index))}
      </Box>
    </Container>
  );
};

export default NotebookViewer;

